// src/lib/timeOff.js
init_supabase();
async function fetchPendingTimeOff(today) {
  const { data, error } = await supabase.from("employee_availability").select("id,employee_id,employee_name,date,kind,note,status,created_at").eq("status", "pending").gte("date", today).order("date", { ascending: true }).limit(200);
  if (error) throw error;
  return data || [];
}

// src/lib/payrollAlerts.js
init_supabase();
async function fetchAutoClosedPeriods() {
  const { data, error } = await supabase.from("salary_periods").select("id,period,closed_at,confirm_deadline,pay_date,status").eq("status", "auto_closed").order("period", { ascending: false }).limit(12);
  if (error) throw error;
  return data || [];
}

// src/lib/quoteRequests.js
init_supabase();
async function fetchPendingQuoteRequests() {
  const { data, error } = await supabase.from("client_requests").select("id,client_id,location_name,category,description,created_at,quote_status").eq("request_type", "quote").or("quote_status.is.null,quote_status.eq.requested").order("created_at", { ascending: false }).limit(50);
  if (error) throw error;
  const rows = data || [];
  const ids = [...new Set(rows.map((r) => r.client_id).filter(Boolean))];
  if (!ids.length) return rows;
  const { data: clients } = await supabase.from("clients").select("id,company_name").in("id", ids);
  const names = new Map((clients || []).map((c) => [c.id, c.company_name]));
  return rows.map((r) => ({ ...r, client_name: names.get(r.client_id) || "" }));
}

